/**
 * Aggregate endpoint used by the Dashboard My Queue and the CAPAs page ?queue=action_assignee filter. Avoids N+1 fetching of per-CAPA action items. The per-CAPA equivalents live at /capas/{id}/action-items but are not yet spec'd; this endpoint is the only one needed by the Dashboard slice.

 * @summary List CAPA action items across all CAPAs, optionally filtered by assignee
 */
export const getListCapaActionItemsUrl = (
  params?: ListCapaActionItemsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/capa-action-items?${stringifiedParams}`
    : `/api/capa-action-items`;
};

